import csv, re, subprocess, glob, os, sys

frames = sorted(glob.glob('/root/keyframes_*.png'))
obj_imgs = {
    'coins': '/root/coin.png',
    'enemies': '/root/enemy.png',
    'turtles': '/root/turtle.png',
}
script = '/root/.codex/skills/object_counter/scripts/count_objects.py'

def count_obj(frame, obj_img):
    cmd = [sys.executable, script, '--tool', 'count', '--input_image', frame, '--object_image', obj_img, '--threshold', '0.9', '--dedup_min_dist', '3']
    result = subprocess.run(cmd, capture_output=True, text=True)
    if result.returncode != 0:
        raise RuntimeError(f"count failed for {frame} with {obj_img}: {result.stderr}")
    m = re.search(r'There are (\d+) objects', result.stdout)
    if not m:
        raise RuntimeError(f"Unexpected output: {result.stdout}")
    return int(m.group(1))

rows = []
for frame in frames:
    counts = {name: count_obj(frame, path) for name, path in obj_imgs.items()}
    rows.append({
        'frame_id': frame,
        'coins': counts['coins'],
        'enemies': counts['enemies'],
        'turtles': counts['turtles'],
    })

out_path = '/root/counting_results.csv'
with open(out_path, 'w', newline='') as f:
    writer = csv.DictWriter(f, fieldnames=['frame_id','coins','enemies','turtles'])
    writer.writeheader()
    writer.writerows(rows)

print(f"Wrote {len(rows)} rows to {out_path}")
